def add(self, product: Product, quantity: int = 1) -> None:
    if quantity <= 0:
        raise ValueError("quantity must be positive")
    if product.sku in self.items:
        self.items[product.sku][1] += quantity
    else:
        self.items[product.sku] = [product, quantity]
